export function getVerifiedGDriveReports(): GDriveVerifiedReportItem[] {
  return GDRIVE_VERIFIED_REPORTS;
}

/**
 * Find verified GDrive report with precision matching
 */
export function findGDriveReportInVerifiedDataset(params: {
  storeCode?: string;
  storeName?: string;
  pic?: string;
  visitDate?: string;
}): GDriveVerifiedReportItem | null {
  const { storeCode, storeName, pic, visitDate } = params;
  const targetCode = String(storeCode || '').toUpperCase().trim();
  const targetName = String(storeName || '').toUpperCase().trim();
  const targetPic = String(pic || '').toLowerCase().trim();

  // 1. Strict match: PIC + storeCode
  if (targetPic && targetCode && targetCode !== 'STORE') {
    const match = GDRIVE_VERIFIED_REPORTS.find((r) => {
      const pMatch = r.personnelName.toLowerCase().includes(targetPic) || targetPic.includes(r.personnelName.toLowerCase());
      const cMatch = String(r.storeCode || '').toUpperCase() === targetCode;
      return pMatch && cMatch;
    });
    if (match) return match;
  }

  // 2. Match by PIC + storeName
  if (targetPic && targetName) {
    const match = GDRIVE_VERIFIED_REPORTS.find((r) => {
      const pMatch = r.personnelName.toLowerCase().includes(targetPic) || targetPic.includes(r.personnelName.toLowerCase());
      const rName = String(r.storeName || '').toUpperCase();
      const nMatch = rName && (rName.includes(targetName) || targetName.includes(rName));
      return pMatch && nMatch;
    });
    if (match) return match;
  }

  // 3. Match by storeCode
  if (targetCode && targetCode !== 'STORE') {
    const match = GDRIVE_VERIFIED_REPORTS.find(
      (r) => String(r.storeCode || '').toUpperCase() === targetCode
    );
    if (match) return match;
  }

  // 4. Match by storeName
  if (targetName) {
    const match = GDRIVE_VERIFIED_REPORTS.find((r) => {
      const rName = String(r.storeName || '').toUpperCase();
      return rName && (rName.includes(targetName) || targetName.includes(rName));
    });
    if (match) return match;
  }

  return null;
}
